import React, { useState } from 'react';
import { Outlet, useLocation } from 'react-router-dom';
import Sidebar from './Sidebar';
import Navbar from './Navbar';
import { usePermissions } from '../../hooks/usePermissions';
import ChatWidget from '../Chat/ChatWidget'; // IMPORT CHAT
import './Layout.css';

const Layout = () => {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const location = useLocation();
  const { canAccessRoute } = usePermissions();
  const accessDenied = !canAccessRoute(location.pathname);

  const toggleSidebar = () => {
    if (window.innerWidth <= 768) {
      setMobileMenuOpen((prev) => !prev);
    } else {
      setSidebarOpen((prev) => !prev);
    }
  };

  const closeMobileMenu = () => setMobileMenuOpen(false);

  return (
    <div className="layout">
      <div
        className={`mobile-backdrop ${mobileMenuOpen ? 'visible' : ''}`}
        onClick={closeMobileMenu}
      />
      <Sidebar
        isOpen={window.innerWidth <= 768 ? mobileMenuOpen : sidebarOpen}
        toggleSidebar={toggleSidebar}
        isMobile={window.innerWidth <= 768}
        onNavigate={closeMobileMenu}
      />
      <div className={`layout-main ${!sidebarOpen && window.innerWidth > 768 ? 'expanded' : ''}`}>
        <Navbar toggleSidebar={toggleSidebar} />
        <main className="layout-content">
          {accessDenied ? (
            <div style={{ padding: '24px' }}>
              <h2>Access Denied</h2>
              <p>You do not have permission to view this page.</p>
            </div>
          ) : (
            <Outlet />
          )}
        </main>
      </div>
      {/* Global AI Chat Widget */}
      <ChatWidget />
    </div>
  );
};

export default Layout;
